        <div class="stat"><div class="v" id="endServed">0</div><div class="l">SERVED</div></div>
        <div class="stat"><div class="v" id="endBest">x0</div><div class="l">BEST STREAK</div></div>
        <div class="stat"><div class="v" id="endMissed">0</div><div class="l">EXPIRED</div></div>
      </div>
