<script>
"use strict";
/* Golden Wok Bistro — a complete cooking game, offline, no libraries. */
const $ = (s) => document.querySelector(s);

const ING = [
  { id: "bun",     name: "BUN",     color: "#e08a2e", icon: "ic-bun",     desc: "Toasted brioche bun",            key: "1" },
  { id: "patty",   name: "PATTY",   color: "#6b3a1e", icon: "ic-patty",   desc: "Grill 6s — watch the timer",    key: "2", cook: 6 },
  { id: "lettuce", name: "LETTUCE", color: "#3fae4a", icon: "ic-lettuce", desc: "Crisp green leaves",            key: "3" },
  { id: "tomato",  name: "TOMATO",  color: "#e23b2e", icon: "ic-tomato",  desc: "Fresh sliced tomato",           key: "4" },
  { id: "cheese",  name: "CHEESE",  color: "#f5a623", icon: "ic-cheese",  desc: "Melty cheddar slice",           key: "5" },
  { id: "fries",   name: "FRIES",   color: "#d92b1f", icon: "ic-fries",   desc: "Fryer 8s — golden & crisp",     key: "6", cook: 8 },
  { id: "drink",   name: "DRINK",   color: "#2f7fc2", icon: "ic-drink",   desc: "Ice-cold cola",                 key: "7" },
  { id: "sauce",   name: "SAUCE",   color: "#c97b2d", icon: "ic-cheese",  desc: "House secret sauce",            key: "8" },
];
const RECIPES = [
  { name: "Classic Burger", items: ["bun", "patty", "lettuce", "tomato"], price: 14 },
  { name: "Cheese Burger",  items: ["bun", "patty", "cheese", "lettuce"], price: 16 },
  { name: "Double Trouble", items: ["bun", "patty", "patty", "cheese", "tomato"], price: 22 },
  { name: "Burger & Fries", items: ["bun", "patty", "lettuce", "fries"], price: 19 },
  { name: "Full Combo",     items: ["bun", "patty", "cheese", "fries", "drink"], price: 26 },
  { name: "Veggie Stack",   items: ["bun", "lettuce", "tomato", "cheese", "sauce"], price: 15 },
  { name: "Saucy Melt",     items: ["bun", "patty", "cheese", "sauce"], price: 18 },
];
const SHIFT = 150, ORDER_TTL = 45, SPAWN_EVERY = 11;

let state = null;
function freshState() {
  return { running: false, over: false, t: SHIFT, coins: 0, served: 0, missed: 0,
    streak: 0, best: 0, orders: [], plate: [], nextOrder: 1, spawnIn: 2,
    grill: { busy: false, t: 0, total: 6, burnt: false },
    fryer: { busy: false, t: 0, total: 8, burnt: false },
    pass: [] };
}
function ingById(id) { return ING.find((x) => x.id === id); }
function recipeByName(n) { return RECIPES.find((r) => r.name === n); }
function fmtTime(s) { return Math.floor(s / 60) + ":" + String(Math.ceil(s % 60)).padStart(2, "0"); }
function beep(freq, dur) {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    beep.ctx = beep.ctx || new AC();
    const o = beep.ctx.createOscillator(), g = beep.ctx.createGain();
    o.frequency.value = freq; o.type = "sine";
    g.gain.setValueAtTime(0.12, beep.ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, beep.ctx.currentTime + dur);
    o.connect(g).connect(beep.ctx.destination); o.start(); o.stop(beep.ctx.currentTime + dur);
  } catch (e) { /* audio is a garnish, never a blocker */ }
}

/* ---------- rendering ---------- */
function renderStations() {
  const wrap = $("#stations");
  wrap.innerHTML = "";
  ING.forEach((ing) => {
    const el = document.createElement("div");
    el.className = "station"; el.dataset.id = ing.id;
    let extra = "";
    if (ing.id === "patty" && state.grill.busy) {
      el.classList.add(state.grill.t >= state.grill.total ? "ready" : "cooking");
      const pct = Math.min(100, (state.grill.t / state.grill.total) * 100);
      extra = state.grill.t >= state.grill.total
        ? '<span class="badge">READY!</span><div class="prog"><i style="width:100%"></i></div>'
        : `<div class="prog"><i style="width:${pct}%"></i></div>`;
    }
    if (ing.id === "fries" && state.fryer.busy) {
      el.classList.add(state.fryer.t >= state.fryer.total ? "ready" : "cooking");
      const pct = Math.min(100, (state.fryer.t / state.fryer.total) * 100);
      extra = state.fryer.t >= state.fryer.total
        ? '<span class="badge">READY!</span><div class="prog"><i style="width:100%"></i></div>'
        : `<div class="prog"><i style="width:${pct}%"></i></div>`;
    }
    if (ing.id === "patty" && state.grill.burnt) extra = '<span class="badge hot">BURNT!</span>';
    if (ing.id === "fries" && state.fryer.burnt) extra = '<span class="badge hot">BURNT!</span>';
    el.innerHTML = `<span class="key">${ing.key}</span><div class="icon ${ing.icon}"></div>
      <div class="name">${ing.name}</div><div class="desc">${ing.desc}</div>${extra}`;
    el.onclick = () => onStation(ing.id);
    wrap.appendChild(el);
  });
}
function renderOrders() {
  const wrap = $("#orders");
  wrap.innerHTML = "";
  state.orders.forEach((o) => {
    const el = document.createElement("div");
    el.className = "ticket" + (o.ttl <= 10 ? " urgent" : "") + (o.matched ? " matched" : "");
    const chips = o.items.map((id) => {
      const n = state.plate.filter((p) => p === id).length;
      const need = o.items.filter((x) => x === id).length;
      return `<span class="chip${n >= need ? " done" : ""}">${ingById(id).name}</span>`;
    }).join("");
    el.innerHTML = `<div class="t-head"><span>#${o.no} ${o.name}</span><span class="price">$${o.price}</span></div>
      <div class="t-items">${chips}</div>
      <div class="t-bar"><i style="width:${(o.ttl / ORDER_TTL) * 100}%"></i></div>`;
    wrap.appendChild(el);
